practice.solution:
from fractions import Fraction

def whole_root(a, n):
    # The whole number r with r ** n == a, for a perfect nth power a >= 0
    r = 0
    while r ** n < a:
        r = r + 1
    return r

def solve(a, k):
    n = abs(k)
    if a < 0 and n % 2 == 0:
        return "not real"
    r = whole_root(abs(a), n)
    if a < 0:
        r = -r
    if k < 0:
        return Fraction(1, r)
    return r

count = int(input())
for i in range(count):
    a = int(input())
    k = int(input())
    if a < 0:
        shown = f"({a})"
    else:
        shown = f"{a}"
    print(f"{shown}^({Fraction(1, k)}) = {solve(a, k)}")
